let duration = phase.duration(in: timing)
let started = Date()
while Date().timeIntervalSince(started) < duration {
    try Task.checkCancellation()
    guard isGuideReady else { throw ScanWorkflowError.trackingLost }
    publishMeasurementContext(acquisition, phase: phase, pattern: pattern)
    let elapsed = Date().timeIntervalSince(sequenceStarted)
    patternCaptureProgressText = String(
        format: "%@ %.1fs / %.1fs",
        pattern.displayTitle,
        min(elapsed, total),
        total
    )
    try await Task.sleep(for: .milliseconds(50))
}

