func reportKey(for pattern: ScanAnalysisPattern) -> String {
    if pattern == .black {
        return blackPhase.reportKey
    }
    switch self {
    case .p0AllOn: return "P0"
    case .p1TopLeftOff: return "P1"
    case .p2TopRightOff: return "P2"
    case .p3BottomRightOff: return "P3"
    case .p4BottomLeftOff: return "P4"
    case .p5AllOff: return "P5"
    }
}

