static func render(_ report: ReportModel) throws -> Data {
    let presentation = ReportPresentation(report)
    let renderer = UIGraphicsPDFRenderer(bounds: pageRect)
    let data = renderer.pdfData { context in
        let layout = Layout(context: context)
        drawPage1(report, presentation, layout)
        drawPage2(presentation, layout)
        layout.beginPage(appendix: true)
        drawAppendix(presentation, layout)
        layout.drawFooter()
    }
    guard !data.isEmpty else { throw ScanWorkflowError.persistenceFailed }
    return data
}
